// CSD_RATIONALE_BEGIN
// Root-cause analysis of all three prior attempts:
//   (A) "!!!!" flooding (attempts 2 & 3): when the model emits a complete
//       expression such as `length // (plant_width + space)` and we do NOT
//       close on IsCompletePrefix, the grammar's only valid "extension" in
//       some states is `!` (error-recovery token), causing hundreds of `!`
//       tokens before EOS or budget exhaust.
//   (B) Intermediate-span last-span extraction (attempt 3, 37 wrong): the
//       evaluator takes the LAST complete span. The model writes individual
//       sub-expressions as separate spans (<<n1*p1>>, <<n2*p2>>, <<n3*p3>>)
//       and the last one is always the final ITEM, not the TOTAL.
//   (C) Unterminated spans (all attempts): EOS or dead-end inside constrained
//       mode before `>>` is emitted; post-loop guard gated on `steps < maxSteps`
//       sometimes false.
//
// Fixes:
//   1. Close on IsCompletePrefix BUT only after >= minSpanLen tokens in the
//      span. minSpanLen=5 prevents early close on trivially short expressions
//      like `n0` (1 tok) or `n0 - 2` (3 toks) while closing `length // (…)`
//      (7+ toks) before `!` flooding starts.
//   2. DeadEndDetection (threshold=2) catches any remaining dead-end states
//      early; on dead-end, RollbackConstrainedToComplete then close or break.
//   3. Post-loop CloseSpanWithinBudget unconditionally handles any still-open
//      span (gated only on insideConstrainedOut, NOT on steps < maxSteps for
//      the call itself since we pass `maxSteps - steps` as the budget).
//   4. Guidance: explicitly tells the model that intermediate << >> is fine but
//      the FINAL << >> MUST be the COMPLETE combined formula, not the last
//      partial step. Provides concrete examples matching GSM_symbolic patterns.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Outside-span branch: implication is vacuous. On RenderedEndsWith("<<"),
//   we set currentConstrainedOut := [] and parser.IsValidPrefix([]) holds by
//   the method precondition `parser.IsValidPrefix([])`.
//
//   Dead-end branch: RollbackConstrainedToComplete postcondition guarantees
//   parser.IsValidPrefix(rC) (complete is stronger than valid, or empty is
//   valid). We then either call CloseConstrainedSpan (which requires
//   IsCompletePrefix and sets insideConstrainedOut := false making the
//   implication vacuous) or break (insideConstrainedOut remains true,
//   currentConstrainedOut = rC which is valid by rollback postcondition).
//
//   Close branch (IsCompletePrefix && >= minSpanLen): CloseConstrainedSpan
//   requires and consumes IsCompletePrefix, sets insideConstrainedOut := false
//   (implication vacuous afterward) and currentConstrainedOut := [].
//
//   Constrained-step branch: AdaptiveConstrainedStep returns eosToken or a
//   token t such that parser.IsValidPrefix(currentConstrainedOut + [t]).
//   AppendConstrainedToken postcondition preserves IsValidPrefix.
//
//   Post-loop CloseSpanWithinBudget: postcondition guarantees
//   `insideOut ==> parser.IsValidPrefix(currentOut)` and
//   `!insideOut ==> currentOut == []`.
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
//   Outside-span branch: steps += 1 before any append; on EOS no append;
//   on normal token generated grows by 1. Bound preserved.
//
//   Dead-end branch: RollbackConstrainedToComplete costs +0 and SHORTENS
//   currentConstrainedOut, so |rG| <= |generated| <= |generatedPrefix| + steps
//   (no steps change). CloseConstrainedSpan appends ">>" (+1 token) and
//   steps += 1; still |generated| <= |generatedPrefix| + steps. On break
//   (empty rollback), no token appended, no step change; post-loop takes over.
//
//   Close branch: steps += 1 and CloseConstrainedSpan appends ">>" (+1 token);
//   bound preserved: |generated| <= |generatedPrefix| + steps.
//
//   Constrained-step branch: steps += 1; on EOS no append; on normal token
//   AppendConstrainedToken appends exactly 1 token. Bound preserved.
//
//   Post-loop: closeBudget = maxSteps - steps; CloseSpanWithinBudget grows
//   generated by at most closeBudget; we set steps := maxSteps; so
//   |generated| <= |generatedPrefix| + old_steps + closeBudget
//             = |generatedPrefix| + maxSteps = |generatedPrefix| + steps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve the math problem step by step. You may use << >> to mark each intermediate symbolic result as you compute it. IMPORTANT: always finish with a final line 'The answer is: <<COMPLETE_FORMULA>>' where COMPLETE_FORMULA is ONE Python expression combining ALL parts of the answer (e.g. <<n1*p1 + n2*p2 + n3*p3>> not just <<n3*p3>>). Use exact variable names from the problem. Use ** for exponentiation, // for integer division, int() to truncate to integer.");

var steps: nat := 0;
var minSpanLen: nat := 5;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  } else {
    var atDeadEnd := helpers.DeadEndDetection(parser, currentConstrainedOut, 2);
    if atDeadEnd {
      // Roll back to last complete parse (or empty)
      var rG, rC := helpers.RollbackConstrainedToComplete(parser, generated, currentConstrainedOut);
      generated := rG;
      currentConstrainedOut := rC;
      if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      } else {
        // Empty rollback or no budget: break to post-loop CloseSpanWithinBudget
        break;
      }
    } else if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSpanLen {
      // Span is complete and long enough — close it, then continue outer loop
      var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, 12, eosToken);
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      var aG, aI, aC := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
      generated := aG;
      insideConstrainedOut := aI;
      currentConstrainedOut := aC;
    }
  }
}

// Post-loop: unconditionally close any still-open span with remaining budget
if insideConstrainedOut {
  if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else if steps < maxSteps {
    var closeBudget := maxSteps - steps;
    var cg, ci, cc := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
  }
}

